mkdir -p /tmp/vecprobe && cd /tmp/vecprobe && cat > Cargo.toml <<'EOF'
[package]
name = "vecprobe"
version = "0.1.0"
edition = "2024"
EOF
mkdir -p src && cat > src/main.rs <<'EOF'
fn main() {
    let mut v: Vec<i32> = vec![3, 1, 2];
    v.sort_by(|a| a);
    println!("{v}");
    let mut w: Vec<i32> = vec![3, 1, 2];
    w.sort_with(|a, b| a.cmp(b));
    println!("{w}");
    let mut x: Vec<i32> = vec![3, 1, 2];
    x.sort();
    println!("{x}");
}
EOF
cargo build 2>&1 | head -30

cd /tmp/vecprobe && cat > src/main.rs <<'EOF'
fn main() {
    let mut v: Vec<i32> = vec![3, 1, 2];
    v.sort_by(|a, b| a.cmp(b));
    for x in v {
        print!("{} ", x);
    }
    print!("\n");
    let mut w: Vec<(&str, i32)> = vec![("b", 2), ("a", 1), ("c", 3)];
    w.sort_by(|a, b| a.1.cmp(b.1).then(a.0.cmp(b.0)));
    for x in w {
        print!("{} {} ", x.0, x.1);
    }
    print!("\n");
}
EOF
cargo build 2>&1 | head -20 && cargo run 2>&1 | tail -5

cd /tmp/vecprobe && cat > src/main.rs <<'EOF'
fn main() {
    let mut v: Vec<i32> = vec![3, 1, 2];
    v.sort_by(|a, b| a.cmp(b));
    for x in v { print!("{} ", x); }
