cd /tmp/vecprobe && cat > src/main.rs <<'EOF'
use std::cmp::Ordering;
fn main() {
    // Ordering API probe
    let o = Ordering::Less;
    print!("{}\n", o.reversed());
    print!("{}\n", Ordering::Equal.then(Ordering::Less));
    print!("{}\n", Ordering::Less.then_with(|()| Ordering::Greater));
    // i32 cmp
    let a = 5i32;
    let b = 3i32;
    print!("{}\n", a.cmp(&b));
    // string comparison
    let s1 = "abc";
    let s2 = "abd";
    print!("{}\n", s1.cmp(s2));
    print!("{}\n", s1.to_lowercase());
    print!("{}\n", "ABC".to_lowercase());
    // u64 parse
    let n = "42".parse::<u64>().ok();
    print!("{}\n", n);
}
EOF
